{
  "summary": "The function fn_16 computes a checksum using a variant of the CRC-16/XMODEM algorithm.",
  "proposed_name": "fn_16",
  "algorithm": "ALG: CRC-16/XMODEM",
  "self_confidence": 1.0,
  "claims": [
    {
      "id": "1",
      "type": "ALG",
      "text": "Implements CRC-16/XMODEM.",
      "asserted_values": [],
      "confidence": 1.0
    },
    {
      "id": "2",
      "type": "CONST",
      "text": "The polynomial used in the CRC-16/XMODEM algorithm is 0x1021.",
      "asserted_values": ["0x1021"],
      "confidence": 1.0
    },
    {
      "id": "3",
      "type": "IO",
      "text": "Returns 0xFFFFFFFFFFFFFFFF when the input length is 0.",
      "asserted_values": ["0xFFFFFFFFFFFFFFFF"],
      "confidence": 1.0,
      "io": {
        "when": "len == 0",
        "returns": "ERR"
      }
    },
    {
      "id": "4",
      "type": "IO",
      "text": "Returns the computed checksum when the input length is greater than 0.",
      "asserted_values": [],
      "confidence": 1.0,
      "io": {
        "when": "len > 0",
        "returns": "len"
      }
    },
    {
      "id": "5",
      "type": "SIDE",
      "text": "Does not write to out.",
      "asserted_values": [],
      "confidence": 1.0
    },
    {
      "id": "6",
      "type": "CF",
      "text": "Iterates over each byte in the input data.",
      "asserted_values": [],
      "confidence": 1.0
    }
  ],
  "recovered_c": "uint64_t fn_16(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len == 0) {\n    return VERA_ERR;\n  }\n\n  uint32_t crc = (uint32_t)((uint64_t)arg >> 32) ^ (uint32_t)arg;\n\n  for (size_t i = 0; i < len; i++) {\n    crc = (uint32_t)in[i] * 0x9d + i + (crc << 7 | crc >> 25);\n  }\n\n  crc = (crc >> 15 ^ crc) * 0x3b9d;\n  return crc >> 13 ^ crc;\n}"
}
